use std::collections::HashMap;
const MAX_SAMPLES: usize = 512;
pub struct RuntimeMetrics {
    buckets: HashMap<&'static str, Vec<u64>>,
}
impl RuntimeMetrics {
    pub fn record_stage_0(&mut self, elapsed_ms: u64) -> Result<(), MetricsError> {
        let bucket = self.buckets.entry("stage_0").or_default();
        bucket.push(elapsed_ms);
        if bucket.len() > MAX_SAMPLES { bucket.remove(0); }
        Ok(())
    }
